import{_ as n,a as d,b as s,c as l,d as h,e as c,f}from"./chunks/safety_geofence.By6Bm39d.js";import{_,C as m,o as u,c as g,al as r,j as t,a,E as o}from"./chunks/framework.7vp1BMOE.js";const F=JSON.parse('{"title":"Safety (Failsafe) Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/config/safety.md","filePath":"en/config/safety.md"}'),p={name:"en/config/safety.md"},T={tabindex:"0"};function b(A,e,C,v,M,y){const i=m("Badge");return u(),g("div",null,[e[18]||(e[18]=r('<h1 id="safety-failsafe-configuration" tabindex="-1">Safety (Failsafe) Configuration <a class="header-anchor" href="#safety-failsafe-configuration" aria-label="Permalink to &quot;Safety (Failsafe) Configuration&quot;">​</a></h1><p>PX4 has a number of safety features to protect and recover your vehicle if something goes wrong:</p><ul><li><em>Failsafes</em> allow you to specify areas and conditions under which you can safely fly, and the <a href="#failsafe-actions">action</a> that will be performed if a failsafe is triggered (for example, landing, holding position, or returning to a specified point). The most important failsafe settings are configured in the <em>QGroundControl</em> <a href="#qgroundcontrol-safety-setup">Safety Setup</a> page. Others must be configured via <a href="./../advanced_config/parameters">parameters</a>.</li><li><a href="#emergency-switches">Safety switches</a> on the remote control can be used to immediately stop motors or return the vehicle in the event of a problem.</li></ul><h2 id="qgroundcontrol-safety-setup" tabindex="-1">QGroundControl Safety Setup <a class="header-anchor" href="#qgroundcontrol-safety-setup" aria-label="Permalink to &quot;QGroundControl Safety Setup&quot;">​</a></h2><p>The <em>QGroundControl</em> Safety Setup page is accessed by clicking the <em>QGroundControl</em> icon, <strong>Vehicle Setup</strong>, and then <strong>Safety</strong> in the sidebar. This includes many of the most important failsafe settings (battery, RC loss etc.) and the settings for the triggered actions <em>Return</em> and <em>Land</em>.</p><p><img src="'+n+'" alt="Safety Setup(QGC)"></p><h2 id="failsafe-actions" tabindex="-1">Failsafe Actions <a class="header-anchor" href="#failsafe-actions" aria-label="Permalink to &quot;Failsafe Actions&quot;">​</a></h2><p>When a failsafe is triggered, the default behavior (for most failsafes) is to enter Hold for <a href="./../advanced_config/parameter_reference#COM_FAIL_ACT_T">COM_FAIL_ACT_T</a> seconds before performing an associated failsafe action. This gives the user time to notice what is happening and override the failsafe if needed. In most cases this can be done by using RC or a GCS to switch modes (note that during the failsafe-hold, moving the RC sticks does not trigger an override).</p><p>The list below shows the set of all failsafe actions, ordered in increasing severity. Note that different types of failsafe may not support all of these actions.</p><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td><a id="act_none"></a>None/Disabled</td><td>No action. The failsafe will be ignored.</td></tr><tr><td><a id="act_warn"></a>Warning</td><td>A warning message will be sent (i.e. to <em>QGroundControl</em>).</td></tr><tr><td><a id="act_hold"></a>Hold mode</td><td>The vehicle will enter <a href="./../flight_modes_mc/hold">Hold mode (MC)</a> or <a href="./../flight_modes_fw/hold">Hold mode (FW)</a> and hover or circle, respectively. VTOL vehicles will hold according to their current mode (MC/FW).</td></tr><tr><td><a id="act_return"></a><a href="./../flight_modes/return">Return mode</a></td><td>The vehicle will enter <em>Return mode</em>. Return behaviour can be set in the <a href="#return-mode-settings">Return Home Settings</a> (below).</td></tr><tr><td><a id="act_land"></a>Land mode</td><td>The vehicle will enter <a href="./../flight_modes_mc/land">Land mode (MC)</a> or <a href="./../flight_modes_fw/land">Land mode (FW)</a>, and land. A VTOL will first transition to MC mode.</td></tr><tr><td><a id="act_disarm"></a>Disarm</td><td>Stops the motors immediately.</td></tr><tr><td><a id="act_term"></a><a href="./../advanced_config/flight_termination">Flight termination</a></td><td>Turns off all controllers and sets all PWM outputs to their failsafe values (e.g. <a href="./../advanced_config/parameter_reference#PWM_MAIN_FAIL1">PWM_MAIN_FAILn</a>, <a href="./../advanced_config/parameter_reference#PWM_MAIN_FAIL1">PWM_AUX_FAILn</a>). The failsafe outputs can be used to deploy a parachute, landing gear or perform another operation. For a fixed-wing vehicle this might allow you to glide the vehicle to safety.</td></tr></tbody></table><p>If multiple failsafes are triggered, the more severe action is taken. For example if both RC and GPS are lost, and manual control loss is set to <a href="#act_return">Return mode</a> and GCS link loss to <a href="#act_land">Land</a>, Land is executed.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The exact behavior when different failsafes are triggered can be tested with the <a href="./safety_simulation">Failsafe State Machine Simulation</a>.</p></div><h3 id="return-mode-settings" tabindex="-1">Return Mode Settings <a class="header-anchor" href="#return-mode-settings" aria-label="Permalink to &quot;Return Mode Settings&quot;">​</a></h3><p><em>Return</em> is a common <a href="#failsafe-actions">failsafe action</a> that engages <a href="./../flight_modes/return">Return mode</a> to return the vehicle to the home position. The default settings for each vehicle are usually suitable, though for fixed wing vehicles you will usually need to define a mission landing.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you want to change the configuration you should carefully read the <a href="./../flight_modes/return">Return mode</a> documentation <em>for your vehicle type</em> to understand the options.</p></div><p>QGC allows users to set some aspects of the return mode and landing behaviour, such as the altitude to fly back, and the loiter time if you need to deploy landing gear.</p><p><img src="'+d+'" alt="Safety - Return Home Settings (QGC)"></p><h3 id="land-mode-settings" tabindex="-1">Land Mode Settings <a class="header-anchor" href="#land-mode-settings" aria-label="Permalink to &quot;Land Mode Settings&quot;">​</a></h3><p><em>Land at the current position</em> is a common <a href="#failsafe-actions">failsafe action</a> (in particular for multicopters), that engages <a href="./../flight_modes_mc/land">Land Mode</a>. The default settings for each vehicle are usually suitable.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you want to change the configuration you should carefully read the <a href="./../flight_modes_fw/land">Land mode</a> documentation <em>for your vehicle type</em> to understand the options.</p></div><p>QGC allows users to set some aspects of the landing behaviour, such as the time to disarm after landing and the descent rate (for multicopters only).</p><p><img src="'+s+'" alt="Safety - Land Mode Settings (QGC)"></p><h2 id="battery-failsafes" tabindex="-1">Battery Failsafes <a class="header-anchor" href="#battery-failsafes" aria-label="Permalink to &quot;Battery Failsafes&quot;">​</a></h2><h3 id="battery-level-failsafe" tabindex="-1">Battery level failsafe <a class="header-anchor" href="#battery-level-failsafe" aria-label="Permalink to &quot;Battery level failsafe&quot;">​</a></h3><p>The low battery failsafe is triggered when the battery capacity drops below battery failafe level values. You can configure both the levels and the failsafe actions at each level in QGroundControl.</p><p><img src="'+l+'" alt="Safety - Battery (QGC)"></p><p>You should set the failsafe levels with <code>Warn &gt; Failsafe &gt; Emergency</code> as shown above. Note that PX4 will warn if the battery drops to the &quot;Warn level&quot; for any of action settings.</p><p>The failsafe actions can then be set to one of:</p>',28)),t("ul",null,[e[5]||(e[5]=t("li",null,[t("p",null,[t("code",null,"0: Warning"),a(" — Warn only.")])],-1)),e[6]||(e[6]=t("li",null,[t("p",null,[t("code",null,"2: Land mode"),a(' — Land at the "Failsafe level".')])],-1)),e[7]||(e[7]=t("li",null,[t("p",null,[t("code",null,"3: Return at critical level, land at emergency level"),a(': (recommended) — Return mode at "Failsafe" level, Land at "Emergency level".')])],-1)),t("li",null,[t("p",null,[e[0]||(e[0]=t("code",null,"4: Return at critical level, terminate at emergency level",-1)),o(i,{type:"tip",text:"main (PX4 v2.0)"}),e[1]||(e[1]=a(' — Return mode at "Failsafe" level, ',-1)),e[2]||(e[2]=t("a",{href:"#act_term"},"Flight termination",-1)),e[3]||(e[3]=a(' at "Emergency level".',-1))]),e[4]||(e[4]=r('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This option may be preferred for vehicles that have a <a href="./../peripherals/parachute">parachute</a>, as it enables controlled landing when there is no power at all.</p><p>If it is not available in the setup screen, <a href="./../advanced_config/parameters">set the parameter</a> directly to <a href="./../advanced_config/parameter_reference#COM_LOW_BAT_ACT">COM_LOW_BAT_ACT = 4</a>.</p></div>',1))])]),e[19]||(e[19]=r('<p>The settings and underlying parameters are shown below.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_LOW_BAT_ACT"></a>Failsafe Action</td><td><a href="./../advanced_config/parameter_reference#COM_LOW_BAT_ACT">COM_LOW_BAT_ACT</a></td><td>Warn, Land, or Return and then Land or Terminate when capacity drops below the trigger levels.</td></tr><tr><td><a id="BAT_LOW_THR"></a>Battery Warn Level</td><td><a href="./../advanced_config/parameter_reference#BAT_LOW_THR">BAT_LOW_THR</a></td><td>Percentage capacity for warnings (or other actions).</td></tr><tr><td><a id="BAT_CRIT_THR"></a>Battery Failsafe Level</td><td><a href="./../advanced_config/parameter_reference#BAT_CRIT_THR">BAT_CRIT_THR</a></td><td>Percentage capacity for Return action (or other actions if a single action selected).</td></tr><tr><td><a id="BAT_EMERGEN_THR"></a>Battery Emergency Level</td><td><a href="./../advanced_config/parameter_reference#BAT_EMERGEN_THR">BAT_EMERGEN_THR</a></td><td>Percentage capacity for triggering Land (immediately) action.</td></tr></tbody></table><h3 id="flight-time-failsafes" tabindex="-1">Flight Time Failsafes <a class="header-anchor" href="#flight-time-failsafes" aria-label="Permalink to &quot;Flight Time Failsafes&quot;">​</a></h3><p>There are several other &quot;battery related&quot; failsafe mechanisms that may be configured using parameters:</p><ul><li>The &quot;remaining flight time for safe return&quot; failsafe (<a href="#COM_FLTT_LOW_ACT">COM_FLTT_LOW_ACT</a>) is engaged when PX4 estimates that the vehicle has just enough battery remaining for a return mode landing. You can configure this to ignore the failsafe, warn, or engage Return mode.</li><li>The &quot;maximum flight time failsafe&quot; (<a href="#COM_FLT_TIME_MAX">COM_FLT_TIME_MAX</a>) allows you to set a maximum flight time after takeoff, at which the vehicle will automatically enter return mode (it will also &quot;warn&quot; at 90% of this time). This is like a &quot;hard coded&quot; estimate of the total flight time in a battery. The feature is disabled by default.</li><li>The &quot;minimum battery&quot; for arming parameter (<a href="#COM_ARM_BAT_MIN">COM_ARM_BAT_MIN</a>) prevents arming in the first place if the battery level is below the specified value.</li></ul><p>The settings and underlying parameters are shown below.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_FLTT_LOW_ACT"></a> Low flight time for safe return action</td><td><a href="./../advanced_config/parameter_reference#COM_FLTT_LOW_ACT">COM_FLTT_LOW_ACT</a></td><td>Action when return mode can only just reach safety with remaining battery. <code>0</code>: None (default), <code>1</code>: Warning, <code>3</code>: Return mode.</td></tr><tr><td><a id="COM_FLT_TIME_MAX"></a> Maximum flight time failsafe level</td><td><a href="./../advanced_config/parameter_reference#COM_FLT_TIME_MAX">COM_FLT_TIME_MAX</a></td><td>Maximum allowed flight time before Return mode will be engaged, in seconds. <code>-1</code>: Disabled (default).</td></tr></tbody></table><h2 id="manual-control-loss-failsafe" tabindex="-1">Manual Control Loss Failsafe <a class="header-anchor" href="#manual-control-loss-failsafe" aria-label="Permalink to &quot;Manual Control Loss Failsafe&quot;">​</a></h2><p>A <a href="./../config/safety#manual-control-loss-failsafe">Manual Control Loss Failsafe</a> is triggered after a <a href="#COM_RC_LOSS_T">manual control loss timeout</a> in which none of the configured <a href="./../config/manual_control">Manual Controllers</a> are available.</p><p><img src="'+h+'" alt="Safety - RC Loss (QGC)"></p><p>The QGCroundControl Safety UI allows you to set the <a href="#failsafe-actions">failsafe action</a> and <a href="#COM_RC_LOSS_T">manual control loss timeout</a>. Users that want to disable this failsafe in specific modes can do so using the parameter <a href="#COM_RCL_EXCEPT">COM_RCL_EXCEPT</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 and the receiver may also need to be configured in order to <em>detect RC loss</em>: <a href="./../config/radio#rc-loss-detection">Radio Setup &gt; RC Loss Detection</a>.</p></div><p>Additional (and underlying) parameter settings are shown below.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_RC_LOSS_T"></a><a href="./../advanced_config/parameter_reference#COM_RC_LOSS_T">COM_RC_LOSS_T</a></td><td>Manual Control Loss Timeout</td><td>Time after last setpoint received from the selected manual control source after which manual control is considered lost. This must be kept short because the vehicle will continue to fly using the last known stick position until the timeout triggers.</td></tr><tr><td><a id="COM_FAIL_ACT_T"></a><a href="./../advanced_config/parameter_reference#COM_FAIL_ACT_T">COM_FAIL_ACT_T</a></td><td>Failsafe Reaction Delay</td><td>Delay in seconds between failsafe condition being triggered (<code>COM_RC_LOSS_T</code>) and failsafe action (RTL, Land, Hold). In this state the vehicle waits in hold mode for the manual control source to reconnect. This might be set longer for long-range flights so that intermittent connection loss doesn&#39;t immediately invoke the failsafe. It can be to zero so that the failsafe triggers immediately.</td></tr><tr><td><a id="NAV_RCL_ACT"></a><a href="./../advanced_config/parameter_reference#NAV_RCL_ACT">NAV_RCL_ACT</a></td><td>Failsafe Action</td><td>Disabled, Loiter, Return, Land, Disarm, Terminate, Hold mode (no failsafe).</td></tr><tr><td><a id="COM_RCL_EXCEPT"></a><a href="./../advanced_config/parameter_reference#COM_RCL_EXCEPT">COM_RCL_EXCEPT</a></td><td>RC Loss Exceptions</td><td>Set modes in which manual control loss is ignored.</td></tr></tbody></table><h3 id="hold-mode-no-failsafe" tabindex="-1">Hold Mode (No Failsafe) <a class="header-anchor" href="#hold-mode-no-failsafe" aria-label="Permalink to &quot;Hold Mode (No Failsafe)&quot;">​</a></h3><p>The <code>Hold mode (no failsafe)</code> action (<code>NAV_RCL_ACT = 7</code>) is a special case that does <em>not</em> enter the failsafe. Instead, if manual control is lost while actively flying a manual mode (such as Position, Altitude, or Stabilized), the vehicle switches to <a href="./../flight_modes_mc/hold">Hold mode</a> as if the user had commanded it: there is no failsafe state and no alarming failsafe notification. This is intended for operations where a switch to Hold on manual control loss is expected and should not be surfaced as a failsafe (for example when operating multiple drones with one GCS).</p><p>If Hold cannot be entered (for example without a valid position estimate), the normal failsafe takes over and escalates from there (Return, Land, Descend, or Terminate as applicable). Manual control loss in any non-manual (auto/offboard) mode is ignored with this setting.</p><h2 id="data-link-loss-failsafe" tabindex="-1">Data Link Loss Failsafe <a class="header-anchor" href="#data-link-loss-failsafe" aria-label="Permalink to &quot;Data Link Loss Failsafe&quot;">​</a></h2><p>The Data Link Loss failsafe is triggered if the connection to the last MAVLink ground station like QGroundControl is lost. Users that want to disable this failsafe in specific modes can do so using the parameter <a href="#COM_DLL_EXCEPT">COM_DLL_EXCEPT</a>.</p><p><img src="'+c+'" alt="Safety - Data Link Loss (QGC)"></p><p>The settings and underlying parameters are shown below.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td>Data Link Loss Timeout</td><td><a href="./../advanced_config/parameter_reference#COM_DL_LOSS_T">COM_DL_LOSS_T</a></td><td>Amount of time after losing the data connection before the failsafe will trigger.</td></tr><tr><td>Failsafe Action</td><td><a href="./../advanced_config/parameter_reference#NAV_DLL_ACT">NAV_DLL_ACT</a></td><td>Disabled, Hold mode, Return mode, Land mode, Disarm, Terminate.</td></tr><tr><td><a id="COM_DLL_EXCEPT"></a>Mode exceptions for DLL failsafe</td><td><a href="./../advanced_config/parameter_reference#COM_DLL_EXCEPT">COM_DLL_EXCEPT</a></td><td>Set modes in which data link loss is ignored.</td></tr></tbody></table><h2 id="geofence-failsafe" tabindex="-1">Geofence Failsafe <a class="header-anchor" href="#geofence-failsafe" aria-label="Permalink to &quot;Geofence Failsafe&quot;">​</a></h2><p>The <em>Geofence Failsafe</em> is triggered when the drone breaches a &quot;virtual&quot; perimeter. In its simplest form, the perimeter is set up as a cylinder centered around the home position. If the vehicle moves outside the radius or above the altitude the specified <em>Failsafe Action</em> will trigger.</p><p>Note that the failsafe action will only trigger once the vehicle has already breached the geofence. If you have a strict no-fly zone for safety or legal reasons, set <a href="./../advanced_config/parameter_reference#GF_ACTION">GF_ACTION</a> to <code>Hold</code> and include a safety margin in your geofences. The margin should be at least:</p><ul><li><strong>Fixed-Wing</strong>: The loiter radius <a href="./../advanced_config/parameter_reference#NAV_LOITER_RAD">NAV_LOITER_RAD</a>.</li><li><strong>Multicopter</strong>: The stopping distance (<code>v^2 / 2a</code> with <code>v</code>=<a href="./../advanced_config/parameter_reference#MPC_XY_VEL_MAX">MPC_XY_VEL_MAX</a> and <code>a</code>=<a href="./../advanced_config/parameter_reference#MPC_ACC_HOR_MAX">MPC_ACC_HOR_MAX</a>).</li></ul><p>Use a margin above those nominal values to account for possible tailwind, position uncertainty, attitude tracking delay, etc.</p><p><img src="'+f+'" alt="Safety - Geofence (QGC)"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>PX4 separately supports more complicated Geofence geometries with multiple arbitrary polygonal and circular inclusion and exclusion areas: <a href="./../flying/geofence">Flying &gt; Geofence</a>.</p></div><p>The settings and underlying <a href="./../advanced_config/parameter_reference#geofence">geofence parameters</a> are shown below.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td>Action on breach</td><td><a href="./../advanced_config/parameter_reference#GF_ACTION">GF_ACTION</a></td><td>None, Warning, Hold mode, Return mode, Terminate, Land.</td></tr><tr><td>Max Radius</td><td><a href="./../advanced_config/parameter_reference#GF_MAX_HOR_DIST">GF_MAX_HOR_DIST</a></td><td>Horizontal radius of geofence cylinder. Geofence disabled if 0.</td></tr><tr><td>Max Altitude</td><td><a href="./../advanced_config/parameter_reference#GF_MAX_VER_DIST">GF_MAX_VER_DIST</a></td><td>Height of geofence cylinder. Geofence disabled if 0.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Setting <code>GF_ACTION</code> to terminate will kill the vehicle on violation of the fence. Due to the inherent danger of this, this function is disabled using <a href="#CBRK_FLIGHTTERM">CBRK_FLIGHTTERM</a>, which needs to be reset to 0 to really shut down the system.</p></div><p>The following settings also apply, but are not displayed in the QGC UI.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="GF_SOURCE"></a>Geofence source</td><td><a href="./../advanced_config/parameter_reference#GF_SOURCE">GF_SOURCE</a></td><td>Set whether position source is estimated global position or direct from the GPS device.</td></tr><tr><td><a id="CBRK_FLIGHTTERM"></a>Circuit breaker for flight termination</td><td><a href="./../advanced_config/parameter_reference#CBRK_FLIGHTTERM">CBRK_FLIGHTTERM</a></td><td>Enables/Disables flight termination action (disabled by default).</td></tr></tbody></table><h2 id="position-estimation-failsafes" tabindex="-1">Position Estimation Failsafes <a class="header-anchor" href="#position-estimation-failsafes" aria-label="Permalink to &quot;Position Estimation Failsafes&quot;">​</a></h2><p>This section describes failsafes related to the quality of the vehicle&#39;s position estimate.</p><h3 id="position-loss-failsafe" tabindex="-1">Position Loss Failsafe <a class="header-anchor" href="#position-loss-failsafe" aria-label="Permalink to &quot;Position Loss Failsafe&quot;">​</a></h3><p>The <em>Position Loss Failsafe</em> is triggered if the quality of the PX4 position estimate falls below acceptable levels (this might be caused by GPS loss) while in a mode that requires an acceptable position estimate.</p><h3 id="position-loss-failsafe-trigger" tabindex="-1">Position Loss Failsafe Trigger <a class="header-anchor" href="#position-loss-failsafe-trigger" aria-label="Permalink to &quot;Position Loss Failsafe Trigger&quot;">​</a></h3><p>The position loss failsafe triggers if the position estimate becomes <em>invalid</em>. There are two mechanisms in PX4 to invalidate the position estimate:</p><ul><li>A timeout since the last sensor data was fused that provides direct speed or horizontal position measurements. <ul><li>Sensors that fall into that category are: GNSS, optical flow, airspeed, VIO, auxiliary global position.</li></ul></li><li>The estimated horizontal position inaccuracy exceeds the threshold <a href="./../advanced_config/parameter_reference#COM_POS_LOW_EPH">COM_POS_LOW_EPH</a><ul><li>This check is only done on hovering systems (rotary-wing vehicles or VTOLs in hover phase). For fixed-wing vehicles, refer to the <a href="#position-accuracy-low-failsafe">Position Accuracy Low</a> section.</li></ul></li></ul><p>The relevant parameters shown below.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="EKF2_NOAID_TOUT"></a><a href="./../advanced_config/parameter_reference#EKF2_NOAID_TOUT">EKF2_NOAID_TOUT</a></td><td>Maximum inertial dead-reckoning time, so the time after the last data sample was received of any sensor that constrains the velocity drift [microseconds].</td></tr><tr><td><a id="COM_POS_FS_EPH"></a><a href="./../advanced_config/parameter_reference#COM_POS_FS_EPH">COM_POS_FS_EPH</a></td><td>Horizontal position error threshold for hovering vehicles (Multicopters and VTOLs in hover). Fixed-wing vehicles have this value set to infinity.</td></tr></tbody></table><h3 id="position-loss-failsafe-action" tabindex="-1">Position Loss Failsafe Action <a class="header-anchor" href="#position-loss-failsafe-action" aria-label="Permalink to &quot;Position Loss Failsafe Action&quot;">​</a></h3><p>Multicopters flying in a position-dependent manual mode, such as <a href="./../flight_modes_mc/position">Position mode</a>, will switch to <a href="./../flight_modes_mc/altitude">Altitude mode</a> if a height estimate is available, and otherwise <a href="./../flight_modes_mc/manual_stabilized">Stabilized mode</a>.</p><p>If manual control is lost as well, or in autonomous modes, PX4 instead attempts <em>Return mode</em> (needs a valid global position and home position), falling back to <em>Land mode</em> (needs a local position estimate), and finally to <a href="./../flight_modes_mc/descend">Descend mode (MC)</a> if no position estimate is available at all.</p><p>Fixed-wing planes flying in a position-dependent manual mode, such as <a href="./../flight_modes_fw/cruise">Cruise mode</a>, will similarly switch to <a href="./../flight_modes_fw/altitude">Altitude mode</a> if a height estimate is available, and otherwise <a href="./../flight_modes_fw/stabilized">Stabilized mode</a>. If manual control is lost as well, or in autonomous modes, PX4 again attempts <em>Return mode</em>, falling back to <em>Land mode</em>, and finally to <a href="./../flight_modes_fw/descend">Descend mode (FW)</a>. In <a href="./../flight_modes_fw/descend">Descend mode (FW)</a>, the vehicle first loiters — circling with a constant roll angle (<a href="./../advanced_config/parameter_reference#FW_GPSF_R">FW_GPSF_R</a>) at the current altitude — for <a href="./../advanced_config/parameter_reference#FW_GPSF_LT">FW_GPSF_LT</a> seconds, before descending.</p><p>VTOLs follow the fixed-wing behaviour above, unless configured to land in hover (<a href="./../advanced_config/parameter_reference#NAV_FORCE_VT">NAV_FORCE_VT</a>), in which case they instead first transition to hover and then follow the multicopter behaviour.</p>',48)),o(i,{type:"tip",text:"main (PX4 v2.0)"}),e[20]||(e[20]=a("You can set ",-1)),e[21]||(e[21]=t("a",{href:"#COM_POS_FS_ACT"},"COM_POS_FS_ACT",-1)),e[22]||(e[22]=a(" to ",-1)),e[23]||(e[23]=t("code",null,"Terminate",-1)),e[24]||(e[24]=a(" to engage ",-1)),e[25]||(e[25]=t("a",{href:"#act_term"},"Flight termination",-1)),e[26]||(e[26]=a(" instead of Descend mode.",-1)),e[27]||(e[27]=t("p",null,"This is is intended for unpiloted vehicles that carry a parachute.",-1)),e[28]||(e[28]=t("p",null,"The relevant parameters are:",-1)),t("table",T,[e[17]||(e[17]=t("thead",null,[t("tr",null,[t("th",null,"Parameter"),t("th",null,"Description")])],-1)),t("tbody",null,[t("tr",null,[e[13]||(e[13]=t("td",null,[t("a",{id:"COM_POS_FS_ACT"}),t("a",{href:"./../advanced_config/parameter_reference#COM_POS_FS_ACT"},"COM_POS_FS_ACT")],-1)),t("td",null,[o(i,{type:"tip",text:"main (PX4 v2.0)"}),e[8]||(e[8]=a(" Action when the failsafe would otherwise Descend. ",-1)),e[9]||(e[9]=t("code",null,"0",-1)),e[10]||(e[10]=a(": Descend if possible (default), ",-1)),e[11]||(e[11]=t("code",null,"1",-1)),e[12]||(e[12]=a(": Terminate.",-1))])]),e[14]||(e[14]=t("tr",null,[t("td",null,[t("a",{id:"FW_GPSF_LT"}),t("a",{href:"./../advanced_config/parameter_reference#FW_GPSF_LT"},"FW_GPSF_LT")]),t("td",null,"Fixed-wing only: Loiter time (waiting at current altitude for position estimation recovery before starting to descend). Set to 0 to disable.")],-1)),e[15]||(e[15]=t("tr",null,[t("td",null,[t("a",{id:"FW_GPSF_R"}),t("a",{href:"./../advanced_config/parameter_reference#FW_GPSF_R"},"FW_GPSF_R")]),t("td",null,"Fixed roll/bank angle while circling.")],-1)),e[16]||(e[16]=t("tr",null,[t("td",null,[t("a",{id:"NAV_FORCE_VT"}),t("a",{href:"./../advanced_config/parameter_reference#NAV_FORCE_VT"},"NAV_FORCE_VT")]),t("td",null,[a("If true, force VTOL takeoff and landing, even in "),t("code",null,"Descend"),a(" failsafe.")])],-1))])]),e[29]||(e[29]=r('<h3 id="position-accuracy-low-failsafe" tabindex="-1">Position Accuracy Low Failsafe <a class="header-anchor" href="#position-accuracy-low-failsafe" aria-label="Permalink to &quot;Position Accuracy Low Failsafe&quot;">​</a></h3><p>In Fixed-wing, the position estimate is never strictly invalidated as long as we have a horizontal aiding source, such as an airspeed sensor. In that case, a separate failsafe can be configured that triggers if the position estimate inacuraccy exceeds the threshold <a href="./../advanced_config/parameter_reference#COM_POS_LOW_EPH">COM_POS_LOW_EPH</a>. The failsafe action is taken if the vehicle is in mission or hold mode, otherwise it is only a warning. The relevant parameters are:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_POS_LOW_EPH"></a><a href="./../advanced_config/parameter_reference#COM_POS_LOW_EPH">COM_POS_LOW_EPH</a></td><td>Position inaccuracy threshold above which COM_POS_LOW_ACT is taken.</td></tr><tr><td><a id="COM_POS_LOW_ACT"></a><a href="./../advanced_config/parameter_reference#COM_POS_LOW_ACT">COM_POS_LOW_ACT</a></td><td>Failsafe action taken when position inaccuracy is above configured threshold.</td></tr></tbody></table><p>Note that if there is no horizontal aiding source anymore, the position estimate is invalidated after <code>EKF2_NOAID_TOUT</code>, and the standard position loss failsafe applies.</p><h3 id="gnss-check-failsafe" tabindex="-1">GNSS Check Failsafe <a class="header-anchor" href="#gnss-check-failsafe" aria-label="Permalink to &quot;GNSS Check Failsafe&quot;">​</a></h3>',5)),o(i,{type:"tip",text:"PX4 v1.18"}),e[30]||(e[30]=r('<p>Triggers on either of:</p><ul><li><strong>Count drop</strong>: receivers with a 3D fix drop below <a href="#SYS_HAS_NUM_GNSS">SYS_HAS_NUM_GNSS</a>. No failsafe action when <code>SYS_HAS_NUM_GNSS=0</code> (default).</li><li><strong>Position divergence</strong>: two receivers disagree beyond their expected separation (configured via <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFX">SENS_GPS0_OFFX/Y</a>, <a href="./../advanced_config/parameter_reference#SENS_GPS1_OFFX">SENS_GPS1_OFFX/Y</a>) plus reported accuracy. Only triggers a failsafe action if <code>SYS_HAS_NUM_GNSS=2</code>.</li></ul><p>At least a warning is emitted, additional failsafe actions can be configured using <a href="#COM_GNSSLOSS_ACT">COM_GNSSLOSS_ACT</a>. Loss of a single GPS when none are required is handled by other GPS health checks.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="SYS_HAS_NUM_GNSS"></a><a href="./../advanced_config/parameter_reference#SYS_HAS_NUM_GNSS">SYS_HAS_NUM_GNSS</a></td><td>Number of usable GNSS receivers required for arming. If two are required then they also need to be consistent.</td></tr><tr><td><a id="COM_GNSSLOSS_ACT"></a><a href="./../advanced_config/parameter_reference#COM_GNSSLOSS_ACT">COM_GNSSLOSS_ACT</a></td><td>Failsafe action when a GNSS failure is detected in flight.</td></tr></tbody></table><h2 id="offboard-loss-failsafe" tabindex="-1">Offboard Loss Failsafe <a class="header-anchor" href="#offboard-loss-failsafe" aria-label="Permalink to &quot;Offboard Loss Failsafe&quot;">​</a></h2><p>The <em>Offboard Loss Failsafe</em> is triggered if the offboard link is lost while under <a href="./../flight_modes/offboard">Offboard control</a>.</p><p>The relevant parameters are shown below:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#COM_OF_LOSS_T">COM_OF_LOSS_T</a></td><td>Delay after loss of offboard connection before the failsafe is triggered.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#COM_OBL_RC_ACT">COM_OBL_RC_ACT</a></td><td>Flight mode to switch to if offboard control is lost.</td></tr></tbody></table><h2 id="traffic-avoidance-failsafe" tabindex="-1">Traffic Avoidance Failsafe <a class="header-anchor" href="#traffic-avoidance-failsafe" aria-label="Permalink to &quot;Traffic Avoidance Failsafe&quot;">​</a></h2><p>The Traffic Avoidance Failsafe allows PX4 to respond to <a href="./../peripherals/adsb_flarm">cooperative traffic reports</a>. The action parameters depend on the conflict model selected when the firmware is built.</p><p>The relevant parameters are shown below:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#DAA_EN">DAA_EN</a></td><td>Enables or disables Detect and Avoid.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#NAV_TRAFF_AVOID">NAV_TRAFF_AVOID</a></td><td>Action for the Crosstrack model.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#DAA_LVL_LOW_ACT">DAA_LVL_LOW_ACT</a></td><td>F3442-mode action for a <code>LOW</code> conflict.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#DAA_LVL_MED_ACT">DAA_LVL_MED_ACT</a></td><td>F3442-mode action for a <code>MEDIUM</code> conflict.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#DAA_LVL_HIGH_ACT">DAA_LVL_HIGH_ACT</a></td><td>F3442-mode action for a <code>HIGH</code> conflict.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#DAA_LVL_CRIT_ACT">DAA_LVL_CRIT_ACT</a></td><td>F3442-mode action for a <code>CRITICAL</code> conflict.</td></tr></tbody></table><p>All action parameters use <code>Disabled</code>, <code>Warn only</code>, <code>Return mode</code>, <code>Land mode</code>, <code>Position Hold mode</code>, and <code>Terminate</code>. See <a href="./../advanced_features/detect_and_avoid">Detect and Avoid</a> for conflict-model and action-transition details.</p><h2 id="remote-id-failsafe" tabindex="-1">Remote ID Failsafe <a class="header-anchor" href="#remote-id-failsafe" aria-label="Permalink to &quot;Remote ID Failsafe&quot;">​</a></h2>',14)),o(i,{type:"tip",text:"PX4 v1.18"}),e[31]||(e[31]=r('<p>The Remote ID failsafe is triggered when the <a href="./../peripherals/remote_id">Remote ID (Open Drone ID)</a> module is not detected or reports as unhealthy while the vehicle is armed.</p><p>The failsafe action and arming behaviour are both configured by the <code>COM_ARM_ODID</code> parameter:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_ARM_ODID"></a><a href="./../advanced_config/parameter_reference#COM_ARM_ODID">COM_ARM_ODID</a></td><td>Remote ID arming check and in-flight failsafe. <code>0</code>: Disabled (default), <code>1</code>: Warning only, <code>2</code>: Error only (prevents arming), <code>3</code>: Return, <code>4</code>: Land, <code>5</code>: Terminate.<br><br>On failsafe:<br>- <code>Error</code>, <code>Return</code>, <code>Land</code> and <code>Terminate</code> prevent arming.<br>- <code>Return</code>, <code>Land</code> and <code>Terminate</code> start the associated action/mode when airborne.</td></tr></tbody></table><h2 id="parachute-health-failsafe" tabindex="-1">Parachute Health Failsafe <a class="header-anchor" href="#parachute-health-failsafe" aria-label="Permalink to &quot;Parachute Health Failsafe&quot;">​</a></h2>',4)),o(i,{type:"tip",text:"PX4 v1.18"}),e[32]||(e[32]=r('<p>The parachute health failsafe is triggered when a <a href="./../peripherals/parachute">MAVLink parachute</a> system is missing or unhealthy while the vehicle is armed or airborne.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_PARACHUTE"></a><a href="./../advanced_config/parameter_reference#COM_PARACHUTE">COM_PARACHUTE</a></td><td>Parachute system monitoring and failsafe action.<br><code>0</code>: Disabled (default), <code>1</code>: <a href="#act_warn">Warning</a>, <code>2</code>: Error, <code>3</code>: <a href="#act_return">Return</a>, <code>4</code>: <a href="#act_land">Land</a>.<br><br>- <code>Warning</code> warns with a failing check but does not prevent arming.<br>- <code>Error</code>, <code>Return</code> and <code>Land</code> prevent arming with a failing check.<br>- <a href="#act_return">Return</a> and <a href="#act_land">Land</a> start the associated action when a failure happens in-flight.</td></tr></tbody></table><h2 id="quad-chute-failsafe" tabindex="-1">Quad-chute Failsafe <a class="header-anchor" href="#quad-chute-failsafe" aria-label="Permalink to &quot;Quad-chute Failsafe&quot;">​</a></h2><p>Failsafe for when a VTOL vehicle can no longer fly in fixed-wing mode, perhaps due to the failure of a pusher motor, airspeed sensor, or control surface. If the failsafe is triggered, the vehicle will immediately switch to multicopter mode and execute the action defined in parameter <a href="#COM_QC_ACT">COM_QC_ACT</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The quad-chute can also be triggered by sending a MAVLINK <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_VTOL_TRANSITION" target="_blank" rel="noreferrer">MAV_CMD_DO_VTOL_TRANSITION</a> message with <code>param2</code> set to <code>1</code>.</p></div><p>The parameters that control when the quad-chute will trigger are listed in the table below.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_QC_ACT"></a><a href="./../advanced_config/parameter_reference#COM_QC_ACT">COM_QC_ACT</a></td><td>Quad-chute action after switching to multicopter flight. Can be set to: <a href="#act_warn">Warning</a>, <a href="#act_return">Return</a>, <a href="#act_land">Land</a>, <a href="#act_hold">Hold</a>.</td></tr><tr><td><a id="VT_FW_QC_HMAX"></a><a href="./../advanced_config/parameter_reference#VT_FW_QC_HMAX">VT_FW_QC_HMAX</a></td><td>Maximum quad-chute height, below which the quad-chute failsafe cannot trigger. This prevents high altitude quad-chute descent, which can drain the battery (and itself cause a crash). The height is relative to ground, home, or the local origin (in preference order, depending on what is available).</td></tr><tr><td><a id="VT_QC_ALT_LOSS"></a><a href="./../advanced_config/parameter_reference#VT_QC_ALT_LOSS">VT_QC_ALT_LOSS</a></td><td>Uncommanded descent quad-chute altitude threshold.<br><br>In altitude controlled modes, such as <a href="./../flight_modes_fw/hold">Hold mode</a>, <a href="./../flight_modes_fw/cruise">Cruise mode</a>, <a href="./../flight_modes_fw/altitude">Altitude mode</a>, or <a href="./../flight_modes_fw/mission">Mission mode</a>, a vehicle should track its current &quot;commanded&quot; altitude setpoint. The quad chute failsafe is triggered if the vehicle falls too far below the commanded setpoint (by the amount defined in this parameter).<br><br>Note that the quad-chute is only triggered if the vehicle continuously loses altitude below the commanded setpoint; it is not triggered if the commanded altitude setpoint increases faster than the vehicle can follow.</td></tr><tr><td><a id="VT_QC_T_ALT_LOSS"></a><a href="./../advanced_config/parameter_reference#VT_QC_T_ALT_LOSS">VT_QC_T_ALT_LOSS</a></td><td>Altitude loss threshold for quad-chute triggering during VTOL transition to fixed-wing flight. The quad-chute is triggered if the vehicle falls this far below its initial altitude before completing the transition.</td></tr><tr><td><a id="VT_FW_MIN_ALT"></a><a href="./../advanced_config/parameter_reference#VT_FW_MIN_ALT">VT_FW_MIN_ALT</a></td><td>Minimum altitude above Home for fixed-wing flight. When the altitude drops below this value in fixed-wing flight the vehicle a quad-chute is triggered.</td></tr><tr><td><a id="VT_FW_QC_R"></a><a href="./../advanced_config/parameter_reference#VT_FW_QC_R">VT_FW_QC_R</a></td><td>Absolute roll threshold for quad-chute triggering in FW mode.</td></tr><tr><td><a id="VT_FW_QC_P"></a><a href="./../advanced_config/parameter_reference#VT_FW_QC_P">VT_FW_QC_P</a></td><td>Absolute pitch threshold for quad-chute triggering in FW mode.</td></tr></tbody></table><h2 id="high-wind-failsafe" tabindex="-1">High Wind Failsafe <a class="header-anchor" href="#high-wind-failsafe" aria-label="Permalink to &quot;High Wind Failsafe&quot;">​</a></h2><p>The high wind failsafe can trigger a warning and/or other mode change when the wind speed exceeds the warning and maximum wind-speed threshold values. The relevant parameters are listed in the table below.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_WIND_MAX"></a><a href="./../advanced_config/parameter_reference#COM_WIND_MAX">COM_WIND_MAX</a></td><td>Wind speed threshold that triggers failsafe action, in m/s (<a href="#COM_WIND_MAX_ACT">COM_WIND_MAX_ACT</a>).</td></tr><tr><td><a id="COM_WIND_MAX_ACT"></a><a href="./../advanced_config/parameter_reference#COM_WIND_MAX_ACT">COM_WIND_MAX_ACT</a></td><td>High wind failsafe action (following <a href="#COM_WIND_MAX">COM_WIND_MAX</a> trigger). Can be set to: <code>0</code>: None (Default), <code>1</code>: <a href="#act_warn">Warning</a>, <code>2</code>: <a href="#act_hold">Hold</a>, <code>3</code>: <a href="#act_return">Return</a>, <code>4</code>: <a href="#act_term">Terminate</a>, <code>5</code>: <a href="#act_land">Land</a>.</td></tr><tr><td><a id="COM_WIND_WARN"></a><a href="./../advanced_config/parameter_reference#COM_WIND_WARN">COM_WIND_WARN</a></td><td>Wind speed threshold that triggers periodic failsafe warning.</td></tr></tbody></table><h2 id="failure-detector" tabindex="-1">Failure Detector <a class="header-anchor" href="#failure-detector" aria-label="Permalink to &quot;Failure Detector&quot;">​</a></h2><p>The failure detector allows a vehicle to take protective actions if it unexpectedly flips, detects a motor failure, or if it is notified by an external failure detection system.</p><p>During <strong>flight</strong>, the failure detector can be used to trigger <a href="./../advanced_config/flight_termination">flight termination</a> if failure conditions are met, which may then launch a <a href="./../peripherals/parachute">parachute</a> or perform some other action.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Acting on a detected failure during flight is deactivated by default (enable by setting the parameter: <a href="#CBRK_FLIGHTTERM">CBRK_FLIGHTTERM=0</a>).</p></div><p>During <strong>takeoff</strong> the failure detector <a href="#attitude-trigger">attitude trigger</a> invokes the <a href="#act_disarm">disarm action</a> if the vehicle flips (disarm kills the motors but, unlike flight termination, will not launch a parachute or perform other failure actions). Note that this check is <em>always enabled on takeoff</em>, irrespective of the <code>CBRK_FLIGHTTERM</code> parameter.</p><p>The failure detector is active in all vehicle types and modes, except for those where the vehicle is <em>expected</em> to do flips (i.e. <a href="./../flight_modes_mc/acro">Acro mode (MC)</a>, <a href="./../flight_modes_fw/acro">Acro mode (FW)</a>, and <a href="./../flight_modes_fw/manual">Manual (FW)</a>).</p><h3 id="altitude-loss-trigger" tabindex="-1">Altitude Loss Trigger <a class="header-anchor" href="#altitude-loss-trigger" aria-label="Permalink to &quot;Altitude Loss Trigger {#altitude-loss-trigger}&quot;">​</a></h3>',17)),o(i,{type:"tip",text:"PX4 v1.18"}),e[33]||(e[33]=a()),o(i,{type:"tip",text:"MC, VTOL only"}),e[34]||(e[34]=r(`<p>The failure detector can be configured to trigger if a rotary-wing vehicle loses too much altitude below its commanded setpoint while in an altitude-controlled flight mode (such as <a href="./../flight_modes_mc/position">Position mode</a> or <a href="./../flight_modes_mc/altitude">Altitude mode</a>).</p><p>If the vehicle descends more than <a href="#FD_ALT_LOSS">FD_ALT_LOSS</a> meters below the setpoint, <a href="./../advanced_config/flight_termination">flight termination</a> is triggered, which may deploy a <a href="./../peripherals/parachute">parachute</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="FD_ALT_LOSS"></a><a href="./../advanced_config/parameter_reference#FD_ALT_LOSS">FD_ALT_LOSS</a></td><td>Altitude loss threshold (m). Flight termination is triggered when the vehicle drops this far below the setpoint. Set to 0 to disable.</td></tr><tr><td><a id="FD_ALT_LOSS_T"></a><a href="./../advanced_config/parameter_reference#FD_ALT_LOSS_T">FD_ALT_LOSS_T</a></td><td>Time (s) the vehicle must remain below the threshold before flight termination is triggered.</td></tr></tbody></table><h3 id="attitude-trigger" tabindex="-1">Attitude Trigger <a class="header-anchor" href="#attitude-trigger" aria-label="Permalink to &quot;Attitude Trigger&quot;">​</a></h3><p>The failure detector can be configured to trigger if the vehicle attitude exceeds predefined pitch and roll values for longer than a specified time.</p><p>The relevant parameters are shown below:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="CBRK_FLIGHTTERM"></a><a href="./../advanced_config/parameter_reference#CBRK_FLIGHTTERM">CBRK_FLIGHTTERM</a></td><td>Flight termination circuit breaker. Unset from 121212 (default) to enable flight termination due to FailureDetector or FMU loss.</td></tr><tr><td><a id="FD_FAIL_P"></a><a href="./../advanced_config/parameter_reference#FD_FAIL_P">FD_FAIL_P</a></td><td>Maximum allowed pitch (in degrees).</td></tr><tr><td><a id="FD_FAIL_R"></a><a href="./../advanced_config/parameter_reference#FD_FAIL_R">FD_FAIL_R</a></td><td>Maximum allowed roll (in degrees).</td></tr><tr><td><a id="FD_FAIL_P_TTRI"></a><a href="./../advanced_config/parameter_reference#FD_FAIL_P_TTRI">FD_FAIL_P_TTRI</a></td><td>Time to exceed <a href="#FD_FAIL_P">FD_FAIL_P</a> for failure detection (default 0.3s).</td></tr><tr><td><a id="FD_FAIL_R_TTRI"></a><a href="./../advanced_config/parameter_reference#FD_FAIL_R_TTRI">FD_FAIL_R_TTRI</a></td><td>Time to exceed <a href="#FD_FAIL_R">FD_FAIL_R</a> for failure detection (default 0.3s).</td></tr></tbody></table><h3 id="motor-failure-trigger" tabindex="-1">Motor Failure Trigger <a class="header-anchor" href="#motor-failure-trigger" aria-label="Permalink to &quot;Motor Failure Trigger&quot;">​</a></h3><p>The failure detector can be configured to detect a motor failure while armed (and trigger an associated action) if the ESC current falls outside expected threshold for more than <a href="#MOTFAIL_TIME">MOTFAIL_TIME</a> seconds. A motor flagged by this current check stays flagged until the vehicle disarms, because the reaction to a failure may stop the motor and thereby make it look healthy again.</p><p>The undercurrent and overcurrent conditions are defined by:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>undercurrent: {esc current} &lt; {MOTFAIL_C2T} * {motor command [0,1]} - {MOTFAIL_OFF}</span></span>
<span class="line"><span>overcurrent:  {esc current} &gt; {MOTFAIL_C2T} * {motor command [0,1]} + {MOTFAIL_OFF}</span></span></code></pre></div><p>The action on motor failure is set with <a href="#CA_FAILURE_MODE">CA_FAILURE_MODE</a>. Actions depend on the vehicle type, and might include warning the user, removing failed motors from control allocation, disabling symmetrically opposite motors, and so on. For more information see <a href="./motor_failure_recovery">Motor Failure Recovery</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="FD_ACT_EN"></a><a href="./../advanced_config/parameter_reference#FD_ACT_EN">FD_ACT_EN</a></td><td>Enable/disable the motor failure trigger completely.</td></tr><tr><td><a id="MOTFAIL_C2T"></a><a href="./../advanced_config/parameter_reference#MOTFAIL_C2T">MOTFAIL_C2T</a></td><td>Slope between normalized motor command [0–1] and expected steady-state current (FD_ACT_MOT_C2T at 100%) (A/%).</td></tr><tr><td><a id="MOTFAIL_OFF"></a><a href="./../advanced_config/parameter_reference#MOTFAIL_OFF">MOTFAIL_OFF</a></td><td>Under/over-current detection threshold offset (A). Added/subtracted to the expected current to form the upper and lower bounds.</td></tr><tr><td><a id="MOTFAIL_TIME"></a><a href="./../advanced_config/parameter_reference#MOTFAIL_TIME">MOTFAIL_TIME</a></td><td>Hysteresis time (s) for which the current threshold must remain exceeded before a motor failure is triggered.</td></tr><tr><td><a id="CA_FAILURE_MODE"></a><a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a></td><td>Failure mode. See <a href="./motor_failure_recovery">Motor Failure Recovery</a>.</td></tr></tbody></table><h3 id="external-automatic-trigger-system-ats" tabindex="-1">External Automatic Trigger System (ATS) <a class="header-anchor" href="#external-automatic-trigger-system-ats" aria-label="Permalink to &quot;External Automatic Trigger System (ATS)&quot;">​</a></h3><p>The <a href="#failure-detector">failure detector</a>, if <a href="#CBRK_FLIGHTTERM">enabled</a>, can also be triggered by an external ATS system. The external trigger system must be connected to flight controller port AUX5 (or MAIN5 on boards that do not have AUX ports), and is configured using the parameters below.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>External ATS is required by <a href="https://webstore.ansi.org/standards/astm/ASTMF332218" target="_blank" rel="noreferrer">ASTM F3322-18</a>. One example of an ATS device is the <a href="https://fruitychutes.com/uav_rpv_drone_recovery_parachutes/sentinel-automatic-trigger-system" target="_blank" rel="noreferrer">FruityChutes Sentinel Automatic Trigger System (SATS-MINI)</a>.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="FD_EXT_ATS_EN"></a><a href="./../advanced_config/parameter_reference#FD_EXT_ATS_EN">FD_EXT_ATS_EN</a></td><td>Enable PWM input on AUX5 or MAIN5 (depending on board) for engaging failsafe from an external automatic trigger system (ATS). Default: Disabled.</td></tr><tr><td><a id="FD_EXT_ATS_TRIG"></a><a href="./../advanced_config/parameter_reference#FD_EXT_ATS_TRIG">FD_EXT_ATS_TRIG</a></td><td>The PWM threshold from external automatic trigger system for engaging failsafe. Default: 1900 ms.</td></tr></tbody></table><h2 id="mission-feasibility-checks" tabindex="-1">Mission Feasibility Checks <a class="header-anchor" href="#mission-feasibility-checks" aria-label="Permalink to &quot;Mission Feasibility Checks&quot;">​</a></h2><p>A number of checks are run to ensure that a mission can only be started if it is <em>feasible</em>. For example, the checks ensures that the first waypoint isn&#39;t too far away, and that the mission flight path doesn&#39;t conflict with any geofences.</p><p>As these are not strictly speaking &quot;failsafes&quot; they are documented in <a href="./../flight_modes_fw/mission#mission-feasibility-checks">Mission Mode (FW) &gt; Mission Feasibility Checks</a> and <a href="./../flight_modes_mc/mission#mission-feasibility-checks">Mission Mode (MC) &gt; Mission Feasibility Checks</a>.</p><h2 id="emergency-switches" tabindex="-1">Emergency Switches <a class="header-anchor" href="#emergency-switches" aria-label="Permalink to &quot;Emergency Switches&quot;">​</a></h2><p>Remote control switches can be configured (as part of <em>QGroundControl</em> <a href="./../config/flight_mode">Flight Mode Setup</a>) to allow you to take rapid corrective action in the event of a problem or emergency; for example, to stop all motors, or activate <a href="#return-switch">Return mode</a>.</p><p>This section lists the available emergency switches.</p><h3 id="kill-switch" tabindex="-1">Kill Switch <a class="header-anchor" href="#kill-switch" aria-label="Permalink to &quot;Kill Switch&quot;">​</a></h3><p>A kill switch immediately stops all motor outputs — if flying, the vehicle will start to fall!</p><p>The motors will restart if the switch is reverted within 5 seconds, after which the vehicle will automatically disarm, and you will need to arm it again in order to start the motors.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>There is also a <a href="#kill-gesture">Kill Gesture</a>, which cannot be reverted.</p></div><h3 id="arm-disarm-switch" tabindex="-1">Arm/Disarm Switch <a class="header-anchor" href="#arm-disarm-switch" aria-label="Permalink to &quot;Arm/Disarm Switch&quot;">​</a></h3><p>The arm/disarm switch is a <em>direct replacement</em> for the default stick-based arming/disarming mechanism (and serves the same purpose: making sure there is an intentional step involved before the motors start/stop). It might be used in preference to the default mechanism because:</p><ul><li>Of a preference of a switch over a stick motion.</li><li>It avoids accidentally triggering arming/disarming in-air with a certain stick motion.</li><li>There is no delay (it reacts immediately).</li></ul><p>The arm/disarm switch immediately disarms (stop) motors for those <a href="./../flight_modes/#flight-modes">flight modes</a> that <em>support disarming in flight</em>. This includes:</p><ul><li><em>Manual mode</em></li><li><em>Acro mode</em></li><li><em>Stabilized</em></li></ul><p>For modes that do not support disarming in flight, the switch is ignored during flight, but may be used after landing is detected. This includes <em>Position mode</em> and autonomous modes (e.g. <em>Mission</em>, <em>Land</em> etc.).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="#auto-disarming-timeouts">Auto disarm timeouts</a> (e.g. via <a href="#COM_DISARM_LAND">COM_DISARM_LAND</a>) are independent of the arm/disarm switch - ie even if the switch is armed the timeouts will still work.</p></div><h3 id="return-switch" tabindex="-1">Return Switch <a class="header-anchor" href="#return-switch" aria-label="Permalink to &quot;Return Switch&quot;">​</a></h3><p>A return switch can be used to immediately engage <a href="./../flight_modes/return">Return mode</a>.</p><h2 id="kill-gesture" tabindex="-1">Kill Gesture <a class="header-anchor" href="#kill-gesture" aria-label="Permalink to &quot;Kill Gesture&quot;">​</a></h2><p>A kill gesture immediately stops all motor outputs — if flying, the vehicle will start to fall!</p><p>The action cannot be reverted without a reboot (this differs from a <a href="#kill-switch">Kill Switch</a>, where the operation can be reverted within 5 seconds).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="MAN_KILL_GEST_T"></a><a href="./../advanced_config/parameter_reference#MAN_KILL_GEST_T">MAN_KILL_GEST_T</a></td><td>Time to hold sticks in gesture position before killing the motors. Default: <code>-1</code> seconds (Disabled).</td></tr></tbody></table><h2 id="arming-disarming-settings" tabindex="-1">Arming/Disarming Settings <a class="header-anchor" href="#arming-disarming-settings" aria-label="Permalink to &quot;Arming/Disarming Settings&quot;">​</a></h2><p>The <a href="./../advanced_config/parameter_reference#commander">commander module</a> has a number of parameters prefixed with <code>COM_ARM</code> that configure whether the vehicle can arm at all, and under what conditions (note that some parameters named with the prefix <code>COM_ARM</code> are used to arm other systems). Parameters prefixed with <code>COM_DISARM_</code> affect disarming behaviour.</p><h3 id="auto-disarming-timeouts" tabindex="-1">Auto-Disarming Timeouts <a class="header-anchor" href="#auto-disarming-timeouts" aria-label="Permalink to &quot;Auto-Disarming Timeouts&quot;">​</a></h3><p>You can set timeouts to automatically disarm a vehicle if it is too slow to takeoff, and/or after landing (disarming the vehicle removes power to the motors, so the propellers won&#39;t spin).</p><p>The <a href="./../advanced_config/parameters">relevant parameters</a> are shown below:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_DISARM_LAND"></a><a href="./../advanced_config/parameter_reference#COM_DISARM_LAND">COM_DISARM_LAND</a></td><td>Timeout for auto-disarm after landing.</td></tr><tr><td><a id="COM_DISARM_PRFLT"></a><a href="./../advanced_config/parameter_reference#COM_DISARM_PRFLT">COM_DISARM_PRFLT</a></td><td>Timeout for auto disarm if vehicle is too slow to takeoff.</td></tr></tbody></table><h3 id="arming-pre-conditions" tabindex="-1">Arming Pre-Conditions <a class="header-anchor" href="#arming-pre-conditions" aria-label="Permalink to &quot;Arming Pre-Conditions&quot;">​</a></h3><p>These parameters can be used to set conditions that prevent arming.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_ARMABLE"></a><a href="./../advanced_config/parameter_reference#COM_ARMABLE">COM_ARMABLE</a></td><td>Enable arming (at all). <code>0</code>: Disabled, <code>1</code>: Enabled (default).</td></tr><tr><td><a id="COM_ARM_BAT_MIN"></a><a href="./../advanced_config/parameter_reference#COM_ARM_BAT_MIN">COM_ARM_BAT_MIN</a></td><td>Minimum battery level for arming. <code>0</code>: Disabled (default). Values: <code>0</code>-<code>0.9</code>,</td></tr><tr><td><a id="COM_ARM_WO_GPS"></a><a href="./../advanced_config/parameter_reference#COM_ARM_WO_GPS">COM_ARM_WO_GPS</a></td><td>Enable arming without GPS. <code>0</code>: Disabled, <code>1</code>: Enabled (default).</td></tr><tr><td><a id="COM_ARM_MIS_REQ"></a><a href="./../advanced_config/parameter_reference#COM_ARM_MIS_REQ">COM_ARM_MIS_REQ</a></td><td>Require valid mission to arm. <code>0</code>: Disabled (default), <code>1</code>: Enabled .</td></tr><tr><td><a id="COM_ARM_AUTH_REQ"></a><a href="./../advanced_config/parameter_reference#COM_ARM_AUTH_REQ">COM_ARM_AUTH_REQ</a></td><td>Requires arm authorisation from an external (MAVLink) system. Flag to allow arming (at all). <code>1</code>: Enabled, <code>0</code>: Disabled (default). Associated configuration parameters are prefixed with <code>COM_ARM_AUTH_</code>.</td></tr><tr><td><a id="COM_ARM_ODID"></a><a href="./../advanced_config/parameter_reference#COM_ARM_ODID">COM_ARM_ODID</a></td><td>Remote ID arming check and in-flight failsafe. <code>0</code>: Disabled (default), <code>1</code>: Warning only, <code>2</code>: Error only, <code>3</code>: Return, <code>4</code>: Land, <code>5</code>: Terminate. See <a href="#remote-id-failsafe">Remote ID Failsafe</a>.</td></tr></tbody></table><p>In addition there are a number of parameters that configure system and sensor limits that make prevent arming if exceeded: <a href="./../advanced_config/parameter_reference#COM_CPU_MAX">COM_CPU_MAX</a>, <a href="./../advanced_config/parameter_reference#COM_ARM_IMU_ACC">COM_ARM_IMU_ACC</a>, <a href="./../advanced_config/parameter_reference#COM_ARM_IMU_GYR">COM_ARM_IMU_GYR</a>, <a href="./../advanced_config/parameter_reference#COM_ARM_MAG_ANG">COM_ARM_MAG_ANG</a>, <a href="./../advanced_config/parameter_reference#COM_ARM_MAG_STR">COM_ARM_MAG_STR</a>.</p><h2 id="further-information" tabindex="-1">Further Information <a class="header-anchor" href="#further-information" aria-label="Permalink to &quot;Further Information&quot;">​</a></h2><ul><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/safety.html" target="_blank" rel="noreferrer">QGroundControl User Guide &gt; Safety Setup</a></li></ul>`,52))])}const w=_(p,[["render",b]]);export{F as __pageData,w as default};
